<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Computer Languages Quiz</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #090b12;
      --panel: #111827;
      --panel-strong: #172033;
      --text: #f8fafc;
      --muted: #b8c2d6;
      --accent: #8b5cf6;
      --accent-strong: #a78bfa;
      --border: #334155;
      --success: #67e8f9;
      --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      line-height: 1.5;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(139, 92, 246, 0.32), transparent 34rem),
        radial-gradient(circle at bottom right, rgba(34, 211, 238, 0.18), transparent 30rem),
        var(--bg);
    }

    .skip-link {
      position: absolute;
      top: 1rem;
      left: 1rem;
      z-index: 2;
      transform: translateY(-160%);
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--text);
      color: var(--bg);
      font-weight: 700;
      transition: transform 160ms ease;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    main {
      width: min(100% - 2rem, 58rem);
      margin: 0 auto;
      padding: 4rem 0;
    }

    .quiz-shell {
      border: 1px solid rgba(148, 163, 184, 0.28);
      border-radius: 1.5rem;
      background: linear-gradient(145deg, rgba(17, 24, 39, 0.94), rgba(15, 23, 42, 0.88));
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .hero {
      padding: clamp(1.5rem, 4vw, 3rem);
      border-bottom: 1px solid rgba(148, 163, 184, 0.22);
      background: linear-gradient(135deg, rgba(139, 92, 246, 0.2), rgba(14, 165, 233, 0.08));
    }

    .eyebrow {
      margin: 0 0 0.75rem;
      color: var(--accent-strong);
      font-size: 0.78rem;
      font-weight: 800;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 5vw, 3.75rem);
      line-height: 1;
      letter-spacing: -0.04em;
    }

    .intro {
      max-width: 42rem;
      margin: 1rem 0 0;
      color: var(--muted);
      font-size: 1.05rem;
    }

    form {
      padding: clamp(1.25rem, 4vw, 2.5rem);
    }

    .form-field {
      margin: 0 0 1.25rem;
      padding: clamp(1rem, 3vw, 1.5rem);
      border: 1px solid var(--border);
      border-radius: 1.25rem;
      background: rgba(15, 23, 42, 0.72);
    }

    fieldset {
      min-width: 0;
      margin: 0;
      padding: 0;
      border: 0;
    }

    legend {
      margin-bottom: 0.6rem;
      padding: 0;
      color: var(--text);
      font-size: 1.18rem;
      font-weight: 800;
    }

    .help-text {
      margin: 0 0 1rem;
      color: var(--muted);
    }

    .choices {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 0.75rem;
    }

    .choice {
      position: relative;
      display: flex;
      gap: 0.75rem;
      align-items: flex-start;
      min-height: 3.25rem;
      padding: 0.9rem 1rem;
      border: 1px solid rgba(148, 163, 184, 0.28);
      border-radius: 1rem;
      background: var(--panel-strong);
      cursor: pointer;
      transition: border-color 160ms ease, background-color 160ms ease, transform 160ms ease;
    }

    .choice:hover {
      border-color: var(--accent-strong);
      background: #1d2840;
      transform: translateY(-1px);
    }

    .choice input {
      width: 1.2rem;
      height: 1.2rem;
      margin: 0.15rem 0 0;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    .choice:has(input:checked) {
      border-color: var(--accent-strong);
      background: rgba(139, 92, 246, 0.2);
    }

    .choice-label {
      font-weight: 700;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 1rem;
      align-items: center;
      margin-top: 1.5rem;
    }

    button {
      min-height: 2.75rem;
      padding: 0.8rem 1.25rem;
      border: 0;
      border-radius: 999px;
      color: white;
      background: linear-gradient(135deg, var(--accent), #06b6d4);
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      box-shadow: 0 12px 28px rgba(139, 92, 246, 0.28);
    }

    button:hover {
      filter: brightness(1.08);
    }

    :focus-visible {
      outline: 3px solid var(--success);
      outline-offset: 3px;
    }

    .result {
      min-height: 1.5rem;
      margin: 0;
      color: var(--success);
      font-weight: 700;
    }

    @media (max-width: 42rem) {
      main {
        width: min(100% - 1rem, 58rem);
        padding: 0.5rem 0;
      }

      .quiz-shell {
        border-radius: 1rem;
      }

      .choices {
        grid-template-columns: 1fr;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
      }
    }

    @media (forced-colors: active) {
      .quiz-shell,
      .form-field,
      .choice,
      button {
        border: 1px solid CanvasText;
      }

      button {
        color: ButtonText;
        background: ButtonFace;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content">
    <section class="quiz-shell" aria-labelledby="quiz-title" data-component="QuizApp">
      <div class="hero">
        <p class="eyebrow">Multi-select quiz</p>
        <h1 id="quiz-title">Computer Languages Quiz</h1>
        <p class="intro">Choose as many answers as apply for each question, then submit your responses.</p>
      </div>

      <form id="quiz-form">
        <div class="form-field" data-component="QuizQuestion">
          <fieldset aria-describedby="language-types-help">
            <legend>1. Which of these are programming languages?</legend>
            <p class="help-text" id="language-types-help">Select every answer that names a language used to write software.</p>
            <div class="choices">
              <label class="choice" for="language-types-0" data-component="Choice">
                <input id="language-types-0" type="checkbox" name="language-types" value="Python">
                <span class="choice-label">Python</span>
              </label>
              <label class="choice" for="language-types-1" data-component="Choice">
                <input id="language-types-1" type="checkbox" name="language-types" value="HTML">
                <span class="choice-label">HTML</span>
              </label>
              <label class="choice" for="language-types-2" data-component="Choice">
                <input id="language-types-2" type="checkbox" name="language-types" value="JavaScript">
                <span class="choice-label">JavaScript</span>
              </label>
              <label class="choice" for="language-types-3" data-component="Choice">
                <input id="language-types-3" type="checkbox" name="language-types" value="BananaScript">
                <span class="choice-label">BananaScript</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="form-field" data-component="QuizQuestion">
          <fieldset>
            <legend>2. Which languages are commonly compiled before running?</legend>
            <div class="choices">
              <label class="choice" for="compiled-languages-0" data-component="Choice">
                <input id="compiled-languages-0" type="checkbox" name="compiled-languages" value="C">
                <span class="choice-label">C</span>
              </label>
              <label class="choice" for="compiled-languages-1" data-component="Choice">
                <input id="compiled-languages-1" type="checkbox" name="compiled-languages" value="Rust">
                <span class="choice-label">Rust</span>
              </label>
              <label class="choice" for="compiled-languages-2" data-component="Choice">
                <input id="compiled-languages-2" type="checkbox" name="compiled-languages" value="Go">
                <span class="choice-label">Go</span>
              </label>
              <label class="choice" for="compiled-languages-3" data-component="Choice">
                <input id="compiled-languages-3" type="checkbox" name="compiled-languages" value="CSS">
                <span class="choice-label">CSS</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="form-field" data-component="QuizQuestion">
          <fieldset>
            <legend>3. Which languages are often used for web development?</legend>
            <div class="choices">
              <label class="choice" for="web-languages-0" data-component="Choice">
                <input id="web-languages-0" type="checkbox" name="web-languages" value="JavaScript">
                <span class="choice-label">JavaScript</span>
              </label>
              <label class="choice" for="web-languages-1" data-component="Choice">
                <input id="web-languages-1" type="checkbox" name="web-languages" value="TypeScript">
                <span class="choice-label">TypeScript</span>
              </label>
              <label class="choice" for="web-languages-2" data-component="Choice">
                <input id="web-languages-2" type="checkbox" name="web-languages" value="PHP">
                <span class="choice-label">PHP</span>
              </label>
              <label class="choice" for="web-languages-3" data-component="Choice">
                <input id="web-languages-3" type="checkbox" name="web-languages" value="Swift">
                <span class="choice-label">Swift</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Submit answers</button>
          <p class="result" id="quiz-result" aria-live="polite"></p>
        </div>
      </form>
    </section>
  </main>

  <script>
    const quizQuestions = ["language-types", "compiled-languages", "web-languages"];

    document.querySelector("#quiz-form").addEventListener("submit", (event) => {
      event.preventDefault();

      const answeredCount = quizQuestions.filter((questionName) => (
        document.querySelectorAll(`input[name="${questionName}"]:checked`).length > 0
      )).length;
      const result = document.querySelector("#quiz-result");

      result.textContent = `Answers submitted. You answered ${answeredCount} of ${quizQuestions.length} questions.`;
    });
  </script>
</body>
</html>
